          frames.append((t,b,l,r))
    frames=[q for q in frames if not any(p!=q and p[0]<=q[0] and p[1]>=q[1] and p[2]<=q[2] and p[3]>=q[3] for p in frames)]
    for t,b,l,r in frames:
      ih,iw=b-t-1,r-l-1
      color=8 if (ih,iw)==(3,3) else 4 if (ih,iw)==(5,5) else 1
      for y in range(t+1,b):
       for x in range(l+1,r):
        if out[y][x]==0: out[y][x]=color
